-- Code generated by togo. PostgreSQL schema fragment (converted from togo 0.2.31's SQLite-only template) — hand-editable; desired state for atlas migrate diff.
CREATE TABLE apps (
    id text PRIMARY KEY DEFAULT gen_random_uuid()::text,
    team_id text NOT NULL,
    server_id text NOT NULL,
    name text NOT NULL,
    repo_url text,
    branch text,
    runtime text,
    port bigint NOT NULL DEFAULT 8080,
    healthcheck_path text NOT NULL DEFAULT '/',
    healthcheck_timeout bigint NOT NULL DEFAULT 60,
    autodeploy_paused boolean NOT NULL DEFAULT false,
    deploy_hook_hash text,
    current_release_id text,
    status text NOT NULL DEFAULT 'new',
    git_installation_id text,
    source text NOT NULL DEFAULT 'git',
    origin_kind text,
    origin_key text,
    origin jsonb,
    imported_state text,
    last_seen_at timestamptz,
    title text,
    description text,
    color text,
    icon text,
    created_by text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Hosbah: an app runs on one server of its team. name is a DNS-label-like slug because it becomes
-- the image repository (hosbah/<name>) and the container prefix (hosbah-<name>-…) on the server (cloudy/… and
-- cloudy-… for images and containers made before the rename).
-- deploy_hook_hash is the SHA-256 of the per-app deploy-hook token; the token itself is shown once.
-- runtime is what the last build detected (dockerfile, or railpack:<provider>).
ALTER TABLE apps ADD CONSTRAINT apps_status_check CHECK (status IN ('new', 'deploying', 'running', 'failed', 'stopped'));
ALTER TABLE apps ADD CONSTRAINT apps_name_check CHECK (name ~ '^[a-z0-9][a-z0-9-]{0,39}$');
ALTER TABLE apps ADD CONSTRAINT apps_port_check CHECK (port BETWEEN 1 AND 65535);
ALTER TABLE apps ADD CONSTRAINT apps_healthcheck_timeout_check CHECK (healthcheck_timeout BETWEEN 5 AND 600);
ALTER TABLE apps ADD CONSTRAINT apps_healthcheck_path_check CHECK (healthcheck_path LIKE '/%');
CREATE UNIQUE INDEX apps_team_name_key ON apps (team_id, name);
CREATE UNIQUE INDEX apps_id_team_key ON apps (id, team_id);
CREATE UNIQUE INDEX apps_deploy_hook_key ON apps (deploy_hook_hash) WHERE deploy_hook_hash IS NOT NULL;
CREATE INDEX apps_server_idx ON apps (server_id);

-- Imported workloads: an app with source 'imported' is something Hosbah found already running on a
-- server (a container, a systemd unit, a Proxmox guest). Hosbah shows it and never deploys, restarts
-- or removes it. origin_key is stable per server (container name, unit name, guest:<vmid>); origin is
-- what discovery reported (image, ports, address, guest_type, cpus, mem_bytes, disk_bytes, status).
-- A git app always has its repository and branch.
ALTER TABLE apps ADD CONSTRAINT apps_source_check CHECK (source IN ('git', 'imported'));
ALTER TABLE apps ADD CONSTRAINT apps_git_repo_check CHECK (source <> 'git' OR (repo_url IS NOT NULL AND branch IS NOT NULL));
ALTER TABLE apps ADD CONSTRAINT apps_origin_kind_check CHECK (origin_kind IS NULL OR origin_kind IN ('container', 'systemd', 'guest'));
ALTER TABLE apps ADD CONSTRAINT apps_imported_state_check CHECK (imported_state IS NULL OR imported_state IN ('running', 'stopped', 'missing'));
ALTER TABLE apps ADD CONSTRAINT apps_imported_origin_check CHECK (source <> 'imported' OR (origin_kind IS NOT NULL AND origin_key IS NOT NULL));
CREATE UNIQUE INDEX apps_server_origin_key ON apps (server_id, origin_key) WHERE source = 'imported';

-- Appearance: how the team presents the app. title is a display name (name stays the slug used in
-- URLs, containers and hostnames and is not editable); description is a short note; color is
-- #RRGGBB; icon is a key from provisioning.ServerIcons (internal/provisioning/appearance.go — keep
-- in step). NULL is the default look. An uploaded logo lives in app_logos.
ALTER TABLE apps ADD CONSTRAINT apps_title_check CHECK (title IS NULL OR char_length(title) BETWEEN 1 AND 80);
ALTER TABLE apps ADD CONSTRAINT apps_description_check CHECK (description IS NULL OR char_length(description) BETWEEN 1 AND 280);
ALTER TABLE apps ADD CONSTRAINT apps_color_check CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$');
ALTER TABLE apps ADD CONSTRAINT apps_icon_check CHECK (icon IS NULL OR icon IN ('server', 'database', 'globe', 'cloud', 'cpu', 'box', 'rocket', 'shield', 'code', 'terminal', 'layers', 'zap', 'flame', 'leaf', 'star', 'heart', 'briefcase', 'home', 'store', 'graduation-cap', 'building', 'gamepad', 'music', 'camera'));
